import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './LeadsPage.css';

export default function LeadsPage({leads,allLeads,employees,onAdd,onUpdate,search}) { const [view,setView]=useState('Table'); return <div className="module-page module-page--leads"><div className="page-heading"><div><div className="eyebrow">SALES WORKSPACE</div><h1>Lead management</h1><p>Capture every enquiry, assign ownership, and keep the next action clear.</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>{const csv=['id,name,phone,email,source,budget,location,status,assigned,next',...leads.map(l=>[l.id,l.name,l.phone,l.email,l.source,l.budget,l.location,l.status,l.assigned,l.next].map(v=>`"${String(v||'').replace(/"/g,'""')}"`).join(','))].join('\n'); const blob=new Blob([csv],{type:'text/csv'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='estateflow-leads.csv';a.click();URL.revokeObjectURL(url)}}>↓ Export CSV</button><button className="btn primary" onClick={onAdd}>＋ Add lead</button></div></div><div className="stats-grid compact-stats"><Stat label="All leads" value={allLeads.length} change="In this workspace" icon="♧" tone="purple" foot="Total captured records"/><Stat label="New leads" value={allLeads.filter(l=>l.status==='New').length} change="Awaiting qualification" icon="✦" tone="blue" foot="Make first contact"/><Stat label="Hot opportunities" value={allLeads.filter(l=>['Hot','Negotiation'].includes(l.status)).length} change="High intent" icon="↗" tone="orange" foot="Prioritise follow-up"/><Stat label="Closed won" value={allLeads.filter(l=>l.status==='Won').length} change="Successful deals" icon="✓" tone="green" foot="Recorded conversions"/></div><section className="panel"><div className="panel-head"><div><h3>All enquiries</h3><p>{leads.length} results · Use status to move a lead through the pipeline</p></div><div className="view-toggle"><button className={view==='Table'?'selected':''} onClick={()=>setView('Table')}>☷ Table</button><button className={view==='Pipeline'?'selected':''} onClick={()=>setView('Pipeline')}>▦ Pipeline</button></div></div>{view==='Table'?<div className="table-wrap"><table><thead><tr><th>LEAD</th><th>PROPERTY NEED</th><th>ASSIGNED TO</th><th>STATUS</th><th>NEXT FOLLOW-UP</th><th>UPDATE</th></tr></thead><tbody>{leads.map((l,i)=><tr key={l.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{l.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div><b>{l.name}</b><small>{l.id} · {l.phone}</small></div></div></td><td><b>{l.type}</b><small className="cell-sub">{l.location||'No location'}</small><small className="cell-sub">{money(l.budget)}</small></td><td><select className="inline-select" value={l.assigned||''} onChange={e=>onUpdate(l.id,{assigned:e.target.value})}><option value="">Unassigned</option>{employees.map(e=><option key={e.id}>{e.name}</option>)}</select></td><td><Status value={l.status}/></td><td>{l.next||'Not scheduled'}</td><td><select className="inline-select" value={l.status} onChange={e=>onUpdate(l.id,{status:e.target.value})}>{['New','Qualified','Hot','Site Visit','Negotiation','Won','Lost'].map(x=><option>{x}</option>)}</select></td></tr>)}</tbody></table>{!leads.length&&<Empty title="No leads found" desc={search?'Try a different search.':'Add your first lead to start building a pipeline.'}/>}</div>:<div className="kanban">{['New','Qualified','Hot','Site Visit','Negotiation','Won'].map(stage=><div className="kanban-col" key={stage}><div className="kanban-head"><span>{stage}</span><b>{leads.filter(l=>l.status===stage).length}</b></div>{leads.filter(l=>l.status===stage).map(l=><div className="kanban-card" key={l.id}><small>{l.id}</small><b>{l.name}</b><span>{l.location}</span><strong>{money(l.budget)}</strong><select value={l.status} onChange={e=>onUpdate(l.id,{status:e.target.value})}>{['New','Qualified','Hot','Site Visit','Negotiation','Won','Lost'].map(x=><option>{x}</option>)}</select></div>)}</div>)}</div>}</section></div>; }
